            toInstant(rs.getTimestamp("maturing_at")),
            toInstant(rs.getTimestamp("judged_at")),
            rs.getBoolean("extension_used"),
            (Integer) rs.getObject("active_curve_version"),
            toInstant(rs.getTimestamp("maturity_hold_from")),
            toInstant(rs.getTimestamp("transferred_at")));

    private final JdbcClient jdbc;

    public BatchRepository(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 按批次号查询批次（含罐编码），不存在返回 empty。
     */
    public Optional<BatchRow> findByBatchNo(String batchNo) {
        return jdbc.sql("""
                        SELECT b.*, t.tank_code
                        FROM fermentation_batch b
                        JOIN fermentation_tank t ON t.id = b.tank_id
                        WHERE b.batch_no = ?
                        """)
                .param(batchNo)
                .query(ROW_MAPPER)
                .optional();
    }

    /**
     * 按批次号查询批次，不存在抛 404。
     */
    public BatchRow requireByBatchNo(String batchNo) {
        return findByBatchNo(batchNo)
                .orElseThrow(() -> new DomainException(404, "batch not found: " + batchNo));
    }

    /**
     * 确保发酵罐存在并返回其 id；罐编码唯一。
     */
    public long findOrCreateTank(String tankCode) {
        var existing = jdbc.sql("SELECT id FROM fermentation_tank WHERE tank_code = ?")
                .param(tankCode)
                .query(Long.class)
                .optional();
        if (existing.isPresent()) {
            return existing.get();
        }
        try {
            return jdbc.sql("INSERT INTO fermentation_tank (tank_code) VALUES (?)")
                    .param(tankCode)
                    .update()
                    .getKey() instanceof Number key ? key.longValue() : 0L;
        } catch (DuplicateKeyException e) {
            return jdbc.sql("SELECT id FROM fermentation_tank WHERE tank_code = ?")
                    .param(tankCode)
                    .query(Long.class)
                    .single();
        }
    }

    /**
     * 创建批次。batch_no 重复返回 409；同一罐已有未转出批次时 active_tank_key 唯一键冲突返回 409，
     * 并发入罐由数据库唯一索引保证只有一个受理。
     */
    public long createBatch(String batchNo, long tankId, Instant filledAt) {
        try {
            Number key = jdbc.sql("""
                            INSERT INTO fermentation_batch
                                (batch_no, tank_id, status, filled_at)
                            VALUES (?, ?, 'FILLED', ?)
                            """)
                    .param(batchNo)
                    .param(tankId)
                    .param(Timestamp.from(filledAt))
                    .update()
                    .getKey();
            return key.longValue();
        } catch (DuplicateKeyException e) {
            throw new DomainException(409, duplicateMessage(e, batchNo, tankId));
        }
    }

    /**
     * 按状态机更新批次状态与阶段时间戳；条件更新失败抛 409，保证流转顺序。
     */
    public int updateStatus(long batchId,
                            BatchStatus expected,
                            BatchStatus next,
                            String timestampColumn,
                            Instant timestamp) {
        int rows = jdbc.sql("""
                        UPDATE fermentation_batch
                        SET status = ?, %s = ?
                        WHERE id = ? AND status = ?
                        """.formatted(timestampColumn))
                .param(next.name())
                .param(Timestamp.from(timestamp))
                .param(batchId)
                .param(expected.name())
                .update();
        if (rows == 0) {
            throw new DomainException(409, "batch status conflict, expected " + expected);
        }
        return rows;
    }

    /**
     * 仅在指定状态下把批次推进到下一状态（不带时间戳列）。
     */
    public int transitionIfCurrent(long batchId, BatchStatus expected, BatchStatus next) {
        int rows = jdbc.sql("UPDATE fermentation_batch SET status = ? WHERE id = ? AND status = ?")
                .param(next.name())
                .param(batchId)
                .param(expected.name())
                .update();
        if (rows == 0) {
            throw new DomainException(409, "batch status conflict, expected " + expected);
        }
        return rows;
    }

    /**
     * 标记后熟开始与保温计时起点（恰 7 天口径以此为准）。
     */
    public void markMaturing(long batchId, Instant maturingAt) {
        int rows = jdbc.sql("""
                        UPDATE fermentation_batch
                        SET status = 'MATURING', maturing_at = ?, maturity_hold_from = ?
                        WHERE id = ? AND status = 'COOLING'
                        """)
                .param(Timestamp.from(maturingAt))
                .param(Timestamp.from(maturingAt))
                .param(batchId)
                .update();
        if (rows == 0) {
            throw new DomainException(409, "batch status conflict, expected COOLING");
        }
    }

    /**
     * 判定不合格时把保温计时起点顺延到判定时刻（延长一次后熟），并标记已使用延长。
     */
    public void applyMaturityExtension(long batchId, Instant judgedAt) {
        int rows = jdbc.sql("""
                        UPDATE fermentation_batch
                        SET extension_used = TRUE, maturity_hold_from = ?, status = 'MATURING'
                        WHERE id = ? AND status = 'REVIEW' AND extension_used = FALSE
                        """)
                .param(Timestamp.from(judgedAt))
                .param(batchId)
                .update();
        if (rows == 0) {
            throw new DomainException(409, "maturity extension already used or status conflict");
        }
    }

    /**
     * 判定后更新判定时刻与可能的状态（合格可继续后续转出流程，记录 judged_at）。
     */
    public void markJudged(long batchId, Instant judgedAt, BatchStatus status) {
        jdbc.sql("UPDATE fermentation_batch SET judged_at = ?, status = ? WHERE id = ?")
                .param(Timestamp.from(judgedAt))
                .param(status.name())
                .param(batchId)
                .update();
    }

    private static Instant toInstant(Timestamp timestamp) {
        return timestamp == null ? null : timestamp.toInstant();
    }

    private static String duplicateMessage(DuplicateKeyException e, String batchNo, long tankId) {
        String message = e.getMostSpecificCause() != null ? e.getMostSpecificCause().getMessage() : "";
        if (message != null && message.contains("uk_active_tank")) {
            return "tank " + tankId + " already has an in-progress batch";
        }
        return "batch already exists: " + batchNo;
    }
}

