     * 查询批次已有的转出时刻，终态幂等返回用。
     */
    public Optional<Instant> findTransferredAt(long batchId) {
        return jdbc.sql("SELECT transferred_at FROM transfer_record WHERE batch_id = ?")
                .param(batchId)
                .query(Instant.class)
                .optional();
    }
}

